import React from 'react';

const SobreNosotros = () => (
  <div className="container">
    <h2>Sobre Nosotros</h2>
    <p>Somos un equipo de profesionales con más de 10 años de experiencia en el sector contable y financiero, comprometidos con la excelencia y la confianza de nuestros clientes.</p>
    <p>Nuestra misión es brindar soluciones integrales y personalizadas para el crecimiento de tu empresa.</p>
  </div>
);

export default SobreNosotros;
